    } else if (s.indexOf('退出登录') >= 0 || s.indexOf('修改密码') >= 0) {
      msg = '已登录';
    } else if (s.indexOf('趣书吧会员登录') >= 0 || s.indexOf('请登录') >= 0) {
      msg = '未登录';
    } else {
